# Source markers of database access (directly or through a service).
DB_MARKERS = (
    "get_asyncdb_session",
    "_repo.",
    "aggregation.",
    "apply_resource_plan",
    "create_quick_project",
)
_SELF_CALL = re.compile(r"self\.(\w+)\(")


def _import_all() -> None:
